		var fixedNavHeight = $('body.wide .fixedTop_ts').height();
		var contentOffset = divToolbarsHeight + fixedNavHeight;
		var narrowShift = divToolbarsHeight;
		if ($('body.wide #angularToolbarInLegacy').length === 1)
		{
			contentOffset -= $('body.wide #angularToolbarInLegacy').outerHeight();
			narrowShift = '0';
		}
		if (!window.matchMedia('screen and (max-width: 70em)').matches) {
			$('body.wide .fixedTop_ts').css('margin-top', divToolbarsHeight + 'px');
			$('#structuralContainer14').css('margin-top', contentOffset + 'px');
		} else {
			$('.fixedTop_ts').css('margin-top', '0');
			$('#structuralContainer14').css('margin-top', narrowShift);
		}
	} else {
		$('.fixedTop_ts').css('position', 'relative');
	}
};
 
